WITH flattened_attrs AS (SELECT id, tier_prices, discounts, ARRAY_MIN(tier_prices) AS lowest_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers) SELECT *, NTILE(3) OVER w_recent AS lowest_price_bucket, LEAD(lowest_price, 1, 0) OVER w_recent AS next_lowest_price, ROW_NUMBER() OVER w_recent AS seq_no, CUME_DIST() OVER (ORDER BY lowest_price NULLS FIRST) AS lowest_price_cume_dist, NTILE(10) OVER (ORDER BY lowest_price DESC, id) AS lowest_price_bucket_2 FROM flattened_attrs WHERE lowest_price < 25 WINDOW w_recent AS (ORDER BY lowest_price, id)
